import { test, expect, BookingPayloadManager } from '../../fixtures/booking.fixture';

test('creates a booking and fetches every submitted field unchanged', async ({ ownedBooking, bookingApi }) => {
  const { payload } = ownedBooking;

  // Step 1: POST a new booking with a unique test payload generated by BookingPayloadManager
  const bookingId = await test.step('Create one uniquely owned booking using API helper', async () => {
    ownedBooking.beginCreation();
    const created = await bookingApi.createBooking(payload);

    expect(created.status, 'POST /booking status').toBe(200);
    expect(created.headers['content-type']).toContain('application/json');

    const result = created.data;
    ownedBooking.recordCreatedId(result.bookingid);
    expect(result.booking, 'Created booking matches submitted payload').toEqual(payload);
    return result.bookingid;
  });

  // Step 2: GET the created booking by ID and verify field persistence
  await test.step('Fetch by ID and compare every submitted field', async () => {
    const fetched = await bookingApi.getBooking(bookingId);

    expect(fetched.status, `GET /booking/${bookingId} status`).toBe(200);
    expect(fetched.headers['content-type']).toContain('application/json');
    expect(fetched.data, 'Full persisted booking matches submitted payload').toEqual(payload);
  });
});

test('partially updates an existing booking using payload manager and API helpers', async ({ ownedBooking, bookingApi }) => {
  const { payload } = ownedBooking;

  // Step 1: Create a uniquely owned booking
  const bookingId = await test.step('Create base booking', async () => {
    ownedBooking.beginCreation();
    const created = await bookingApi.createBooking(payload);

    expect(created.status, 'POST /booking status').toBe(200);
    ownedBooking.recordCreatedId(created.bookingId);
    return created.bookingId;
  });

  // Step 2: Generate a partial update payload using BookingPayloadManager
  const updatePayload = BookingPayloadManager.createPartialUpdate({
    totalprice: 350,
    additionalneeds: 'Late Checkout, High Floor',
  });

  // Step 3: Send PATCH request and verify that modified fields update and original fields persist
  await test.step('Patch booking and verify updated response', async () => {
    const patched = await bookingApi.partialUpdateBooking(bookingId, updatePayload);

    expect(patched.status, `PATCH /booking/${bookingId} status`).toBe(200);
    expect(patched.headers['content-type']).toContain('application/json');
    expect(patched.data.totalprice, 'Updated totalprice matches').toBe(350);
    expect(patched.data.additionalneeds, 'Updated additionalneeds matches').toBe('Late Checkout, High Floor');
    // Ensure unpatched fields remain identical
    expect(patched.data.firstname, 'Firstname remains unchanged').toBe(payload.firstname);
    expect(patched.data.lastname, 'Lastname remains unchanged').toBe(payload.lastname);
  });
});
